#!/usr/bin/env python3
"""Independently read back only named source metadata and assemble the bounded handback."""
import collections,datetime,hashlib,itertools,json,os,subprocess
from pathlib import Path
P=Path('/tmp/m6-integration-source-intersections-t5-20261103')
ROOT='/workspace/repos/pixelelated/distribution.worktrees/m6-renovation-plan-346'
C='71bee11968b8a2f3b0165004f21c5498a47a6054';N='8ebaf8daad8eaac6331dff6fc048fb4411d7decb'
assert set(os.sched_getaffinity(0))==set(range(8,24))
def sha(b):return hashlib.sha256(b).hexdigest()
def dump(path,data):path.write_text(json.dumps(data,sort_keys=True,indent=2)+'\n')
inputs=json.loads((P/'result/slice-inputs.json').read_bytes())
deltas=json.loads((P/'result/net-source-deltas.json').read_bytes())
pairs=json.loads((P/'result/pairwise-intersections.json').read_bytes())
summary=json.loads((P/'result/summary.json').read_bytes())
receipts=[];verified=[]
def git(*args):
    argv=['git','-C',ROOT,'--literal-pathspecs',*args];start=datetime.datetime.now(datetime.timezone.utc).isoformat()
    q=subprocess.run(argv,capture_output=True,env=dict(os.environ,GIT_OPTIONAL_LOCKS='0'))
    receipts.append({'argv':argv,'start':start,'end':datetime.datetime.now(datetime.timezone.utc).isoformat(),'rc':q.returncode,'stdout_bytes':len(q.stdout),'stdout_sha256':sha(q.stdout),'stderr_sha256':sha(q.stderr)})
    assert q.returncode==0,q.stderr
    return q.stdout
def tree(pin,paths):
    out={}
    for offset in range(0,len(paths),200):
        raw=git('ls-tree','-l','-z',pin,'--',*paths[offset:offset+200])
        for row in raw.split(b'\0'):
            if row:
                h,path=row.split(b'\t',1);mode,kind,oid,size=h.decode().split()
                out[path.decode()]={'mode':mode,'type':kind,'oid':oid,'bytes':int(size) if size!='-' else None}
    return out
for sl in inputs['slices']:
    if sl['status']!='bound':continue
    rows=deltas[str(sl['k'])];keys=sorted(rows)
    raw=git('diff','--name-status','--no-renames','--no-ext-diff','--no-textconv','-z',sl['reviewed'],sl['fixed'],'--')
    items=raw.split(b'\0');items=items[:-1] if items[-1:]==[b''] else items
    assert len(items)%2==0
    observed={items[i+1].decode():items[i].decode() for i in range(0,len(items),2)}
    assert len(observed)==sl['total_net_changed_paths']
    assert all(observed[path]==row['status'] for path,row in rows.items())
    for field,pin in [('reviewed',sl['reviewed']),('accepted',sl['fixed'])]:
        actual=tree(pin,keys)
        for key,row in rows.items():assert actual.get(key)==row[field],(sl['k'],field,key)
    verified.append({'k':sl['k'],'included_paths':len(keys),'name_status_reconciles':True,'reviewed_and_fixed_tree_metadata_exact':True})
dump(P/'result/independent-metadata-readback.json',{'rows':verified,'commands':receipts})
# Blank field evidence is preserved literally rather than replaced by a branch or guessed handback.
gap_body=json.loads((P/'issue-669.json').read_bytes())['body']
gap_lines=[{'line':i+1,'text':line} for i,line in enumerate(gap_body.splitlines()) if line.startswith(('reviewed-at:','fixed-at:'))]
gap={'k':22,'issue':669,'body_sha256':sha(gap_body.encode()),'literal_headers':gap_lines,
     'criterion_disagreement':[{'line':i+1,'text':line} for i,line in enumerate(gap_body.splitlines()) if line.startswith('- [x]') and 'checklist' in line and 'reviewed-at:' in line],
     'impact':'T22 source delta and its 29 potential pair comparisons are not computable from the dispatched body contract. No refs inferred; root/P1 own field reconciliation.'}
dump(P/'result/unresolved.json',[gap])
paths={}
for sk,rows in deltas.items():
    for path,row in rows.items():
        if row['role']=='shared_ledger_planning_metadata':continue
        rec=paths.setdefault(path,{'path':path,'role':row['role'],'slices':[],'coordinator':row['coordinator'],'next':row['next']})
        assert rec['coordinator']==row['coordinator'] and rec['next']==row['next']
        rec['slices'].append(int(sk))
coord_next=[v for _,v in sorted(paths.items()) if v['coordinator']!=v['next']]
different_target=[]
for sk,rows in deltas.items():
    for path,r in rows.items():
        if r['role']=='shared_ledger_planning_metadata':continue
        for anchor in ['coordinator','next']:
            if r[anchor+'_comparison']=='different_from_reviewed_and_accepted':
                different_target.append({'k':int(sk),'path':path,'anchor':anchor,'reviewed':r['reviewed'],'accepted':r['accepted'],'target':r[anchor]})
dump(P/'result/coordinator-next-intersections.json',{'union_source_paths':len(paths),'coordinator_next_different_on_source_keys':coord_next,'target_different_from_both_endpoint_identities':different_target})
collision_paths=collections.defaultdict(set)
for row in pairs['intersection_rows']:
    if row['role']=='source':collision_paths[row['path']].update([row['a'],row['b']])
# TSV is ordinary private metadata, not an exported source tree.
lines=['path\tslices\tpair_class']
for path,ks in sorted(collision_paths.items()):lines.append(path+'\t'+','.join('T'+str(k) for k in sorted(ks))+'\tdifferent accepted identities; no fixed-tip ancestry')
(P/'result/source-collisions.tsv').write_text('\n'.join(lines)+'\n')
slice_lines=['k\tcanonical_id\tissue\treviewed_commit\tfixed_commit\tsource_paths\tproduct_tool_paths\tledger_planning_paths\tstatus']
for s in inputs['slices']:
    slice_lines.append('\t'.join(str(s.get(k,'')) for k in ['k','id','issue','reviewed','fixed','source_net_paths','product_tool_build_net_paths','shared_ledger_planning_net_paths','status']))
(P/'result/slice-summary.tsv').write_text('\n'.join(slice_lines)+'\n')
aggregate={label:dict(collections.Counter(row[label+'_comparison'] for rows in deltas.values() for row in rows.values() if row['role']!='shared_ledger_planning_metadata')) for label in ['coordinator','next']}
summary.update({'unique_collision_paths':len(collision_paths),'coordinator_next_different_on_source_keys':len(coord_next),
                'source_target_class_counts':aggregate,'all_29_bound_fixed_commits_descend_from_pinned_next':all(s.get('ancestry',{}).get('next_is_ancestor_fixed') for s in inputs['slices'] if s['status']=='bound'),
                'none_of_29_fixed_commits_is_ancestor_of_pinned_next_or_coordinator':all(not s['ancestry']['fixed_is_ancestor_next'] and not s['ancestry']['fixed_is_ancestor_coordinator'] for s in inputs['slices'] if s['status']=='bound'),
                'unresolved': [gap],'independent_source_metadata_readbacks':len(verified)})
dump(P/'result/summary-final.json',summary)
print('FINAL SUMMARY',json.dumps(summary,indent=2))
print('SOURCE COLLISION PATHS',json.dumps({k:sorted(v) for k,v in collision_paths.items()},indent=2))
print('COORDINATOR/NEXT DIFFERING SOURCE KEYS',json.dumps([{'path':r['path'],'slices':r['slices']} for r in coord_next],indent=2))
print('OUTPUT FILE SIZES',json.dumps({f.name:f.stat().st_size for f in (P/'result').iterdir() if f.is_file()}))
